import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long k = Long.parseLong(next());
        long n = Long.parseLong(next());
        long[] prices = new long[(int) n];
        for (int i = 0; i < prices.length; i++) prices[i] = Long.parseLong(next());

        if (k >= n / 2) {
            long total = 0;
            for (int i = 1; i < n; i++) if (prices[i] > prices[i - 1]) total += prices[i] - prices[i - 1];
            System.out.println(total);
        } else {
            int trades = (int) k;
            long[] buy = new long[trades + 1];
            long[] sell = new long[trades + 1];
            Arrays.fill(buy, -1000000000000000000L);
            for (int i = 0; i < n; i++) {
                long p = prices[i];
                for (int j = 1; j <= trades; j++) {
                    buy[j] = Math.max(buy[j], sell[j - 1] - p);
                    sell[j] = Math.max(sell[j], buy[j] + p);
                }
            }
            System.out.println(sell[trades]);
        }
    }
}
